#include <vector>
#include <algorithm>

void output_result(unsigned v)
{
    std::cout << v << '\n';
}

void process(const std::vector<unsigned>& data)
{
    auto minmax = std::minmax_element(data.begin(), data.end());
    unsigned min_val = *minmax.first;
    unsigned max_val = *minmax.second;
    output_result(min_val + (max_val - min_val) / 2);
}

int main()
{
    size_t size;
    std::cin >> size;
    std::vector<unsigned> numbers(size);
    for (size_t i = 0; i < size; ++i)
        std::cin >> numbers[i];

    process(numbers);
    return 0;
}
