import java.util.*;
import java.util.stream.*;

public class Main {
    public static void outputResult(long v) {
        System.out.println(v);
    }

    public static void process(List<Long> data) {
        long minVal = Collections.min(data);
        long maxVal = Collections.max(data);
        outputResult(minVal + (maxVal - minVal) / 2);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int size = scanner.nextInt();
        List<Long> numbers = new ArrayList<>(size);
        for (int i = 0; i < size; i++) {
            numbers.add(scanner.nextLong());
        }
        process(numbers);
        scanner.close();
    }
}
